"""hero_wave3 프롬프트·facing 작성(안아트 2026-11-06, hero_exp2/make_prompts.py 형식). 외형 = 정식 초상(hero_wave3 QA 통과본) 기준.
병종 견본(layout): 3x3 견본은 sword·mage·healer·archer·cavalry 5종만 있음 -> spear·gunner·naval 은 sword 견본(기존 exp2 tipu_sultan·spear 관례).
승격 17명(초상 = public/assets/portraits/npc/<code>.webp)은 portrait 경로를 덮어쓴다.
실행: python docker/gemini/hero_wave3/make_prompts.py (프로젝트 루트)"""
import json
from pathlib import Path
G = Path(__file__).resolve().parent
layouts = json.loads((G.parent / 'hero_exp1/sprite_prompts.json').read_text(encoding='utf-8'))['layouts']
H = {}
LAY = {'sword': 'sword', 'spear': 'sword', 'gunner': 'sword', 'naval': 'sword', 'mage': 'mage', 'archer': 'archer', 'cavalry': 'cavalry'}
M = '기마 모습(말과 기수가 한 캐릭터)'


def add(code, name, ut, desc, back, side, forbid, verify, mounted=None, portrait=None):
    mounted = (ut == 'cavalry') if mounted is None else mounted
    d = {'name': name, 'unit_type': ut, 'layout': LAY[ut], 'desc': desc, 'back': back, 'side': side, 'forbid': forbid, 'verify': verify}
    if mounted:
        d['mounted'] = True
    if portrait:
        d['portrait'] = portrait
    H[code] = d


